	(217, '_elementor_free_to_pro_upsell', 'a:2:{s:7:"timeout";i:1789060182;s:5:"value";s:723:"[{"id":"animated_headline","imageSrc":"https:\\/\\/assets.elementor.com\\/free-to-pro-upsell\\/v1\\/images\\/animated_headline.jpg"},{"id":"video_playlist","imageSrc":"https:\\/\\/assets.elementor.com\\/free-to-pro-upsell\\/v1\\/images\\/video_playlist.jpg"},{"id":"cta","imageSrc":"https:\\/\\/assets.elementor.com\\/free-to-pro-upsell\\/v1\\/images\\/cta.jpg"},{"id":"testimonial_widget","imageSrc":"https:\\/\\/assets.elementor.com\\/free-to-pro-upsell\\/v1\\/images\\/testimonial_widget.jpg"},{"id":"image_carousel","imageSrc":"https:\\/\\/assets.elementor.com\\/free-to-pro-upsell\\/v1\\/images\\/image_carousel.jpg"},{"id":"connect-pro-upgrade","imageSrc":"https:\\/\\/assets.elementor.com\\/free-to-pro-upsell\\/v1\\/images\\/connect-pro-upgrade.jpg"}]";}', 'off'),
	(218, '_elementor_notifications_data', 'a:2:{s:7:"timeout";i:1789099784;s:5:"value";s:3796:"[{"id":"webinar-audit-fix-ai","title":"Webinar: Audit and fix your site with AI","description":"Join Miriam and Ronnie on Tuesday, September 15th, 16:00 CEST to see how to analyze your site, surface SEO and usability gaps worth fixing, and how Angie implements the fixes for you in minutes.","topic":"Webinar","imageSrc":"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/webinar-fix-150926.png","chipTags":["Webinar"],"link":"https:\\/\\/go.elementor.com\\/go-pro-notification-webinar-audit-fix-ai\\/","readMoreText":"Watch the session here"},{"id":"webinar-cinematic-scroll-mcp-rewatch","title":"Webinar rewatch: Cinematic scroll & MCP teaser","description":"See how to generate a full page from simple prompts, add an immersive cinematic scroll experience to your site and get a first look at the Elementor MCP that\'s coming soon.","topic":"Webinar","imageSrc":"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/webinar-cinematic-scroll-mcp.png","chipTags":["Webinar"],"link":"https:\\/\\/www.youtube.com\\/watch?v=qyr0VGwpA8I","readMoreText":"Learn more"},{"id":"angie-build-full-page","title":"Generate full Elementor pages","description":"Describe the layout you need and get a complete page, or generate individual sections like hero areas, feature blocks, and pricing tables one at a time. Every result can be matched to your site\'s existing styles or follow any new design instructions you give.","topic":"Angie","imageSrc":"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/angie-build-full-page.png","chipTags":["Angie"],"link":"https:\\/\\/go.elementor.com\\/go-pro-notification-angie-build-with-prompts\\/","readMoreText":"Learn More"},{"id":"angie-build-design-system","title":"Turn a screenshot into a design system","description":"Describe your site\'s look, upload a screenshot, or paste your values, and get a base design system built automatically: colors and typography as reusable variables and classes or global styles. Every layout Angie builds draws from the same system, so new pages stay consistent.","topic":"Angie","imageSrc":"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/angie-build-design-system.png","chipTags":["Angie"],"link":"https:\\/\\/go.elementor.com\\/go-pro-notification-angie-build-with-prompts\\/","readMoreText":"Learn More"},{"id":"angie-super-community","title":"Angie Community Library","description":"Browse a library of snippets and widgets built by other Angie users, import any of them into your site, without consuming any credits or remix them with a prompt to match your brief. Every snippet is vetted by the Elementor team. You can also submit your own work for the community to discover.","topic":"Angie","imageSrc":"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/angie-community.png","chipTags":["Angie"],"link":"https:\\/\\/go.elementor.com\\/go-pro-notification-angie-community\\/","readMoreText":"Browse library"},{"id":"angie-super-admin","title":"Super Admin Mode","description":"Revolutionize your WordPress workflow with Super Admin Mode. Perform root-level WordPress operations through natural language - bulk post and product updates, PHP error diagnosis, and more.","topic":"Angie","imageSrc":"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/angie-super-admin.png","chipTags":["Angie"],"link":"https:\\/\\/go.elementor.com\\/go-pro-notification-angie-super-admin\\/","readMoreText":"Learn More"},{"id":"one-launch","title":"Introducing Elementor One","description":"The complete website building experience. All the tools to create, optimize, and manage websites, unified under one roof.","imageSrc":"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/one-launch.png","chipTags":["New Launch"],"cta":"Explore Elementor One","ctaLink":"https:\\/\\/go.elementor.com\\/launch-whats-new"}]";}', 'off'),
	(221, 'elementor_remote_info_feed_data', 'a:3:{i:0;a:5:{s:5:"title";s:43:"Introducing Angie: Agentic AI for WordPress";s:7:"excerpt";s:365:"Meet Angie, agentic AI purpose-built for WordPress. Angie understands your site, connects to your tools, and takes real actions on your behalf. Its first capability, Angie Code, lets you describe any WordPress feature you can imagine and have it built for you in minutes. Production-ready, fully integrated with your site, and safe to test before it ever goes live.";s:7:"created";i:1774270910;s:5:"badge";s:3:"NEW";s:3:"url";s:142:"https://elementor.com/blog/introducing-angie-agentic-ai-for-wordpress/?utm_source=wp-overview-widget&utm_medium=wp-dash&utm_campaign=news-feed";}i:1;a:5:{s:5:"title";s:59:"The atomic foundation of version 4 is ready for real sites!";s:7:"excerpt";s:296:"The alpha phase is complete. Version 4 is now in beta, and the atomic foundation is ready to be used on real sites! This is the final step before the official release of version 4.0, activating the new features automatically on new sites, and becoming the default editing experience in Elementor.";s:7:"created";i:1770651621;s:5:"badge";s:3:"NEW";s:3:"url";s:113:"https://elementor.com/blog/editor-4-beta/?utm_source=wp-overview-widget&utm_medium=wp-dash&utm_campaign=news-feed";}i:2;a:5:{s:5:"title";s:79:"Introducing Elementor 3.33: Variables Manager, Custom CSS, Blend Modes, & more!";s:7:"excerpt";s:340:"Elementor 3.33 builds on the foundation of Editor V4, continuing our mission to create a faster, more scalable, and more intuitive design experience for Web Creators. With the addition of the Variables Manager, element-level Custom CSS, Background Clipping, and Blend Modes, designers have more creative precision and consistency than ever.";s:7:"created";i:1762944115;s:5:"badge";s:3:"NEW";s:3:"url";s:145:"https://elementor.com/blog/elementor-333-v4-variables-manager-custom-css/?utm_source=wp-overview-widget&utm_medium=wp-dash&utm_campaign=news-feed";}}', 'off'),
	(224, '_elementor_v4_promotions', 'a:2:{s:7:"timeout";i:1789060186;s:5:"value";s:3523:"[{"customCss":{"title":"Custom CSS","content":"Add custom CSS to refine and enrich the appearance of any element on your site.","ctaUrl":"https:\\/\\/go.elementor.com\\/go-pro-style-custom-css\\/","image":"https:\\/\\/assets.elementor.com\\/packages\\/v1\\/images\\/custom_css_promotion.png"},"displayConditions":{"title":"Display conditions","content":"Control when and where elements are shown across your site.","ctaUrl":"https:\\/\\/go.elementor.com\\/go-pro-display-conditions-modal\\/","image":"https:\\/\\/assets.elementor.com\\/packages\\/v1\\/images\\/display_conditions_promotion.png"},"attributes":{"title":"Attributes","content":"Add custom attributes when you need deeper customization and better accessibility.","ctaUrl":"https:\\/\\/go.elementor.com\\/go-pro-attributes-modal\\/","image":"https:\\/\\/assets.elementor.com\\/packages\\/v1\\/images\\/attributes_promotion.png"},"Portfolio":{"title":"Portfolio","content":"Upgrade to build dynamic portfolio grids featuring interactive category filtering and engaging hover effects designed to captivate your site visitors.","image":"https:\\/\\/assets.elementor.com\\/packages\\/v1\\/images\\/Portfolio_promotion.png"},"Form":{"title":"Form","content":"Upgrade to build advanced forms featuring custom fields, multi-step layouts, automated email notifications, and direct CRM integrations.","image":"https:\\/\\/assets.elementor.com\\/packages\\/v1\\/images\\/Form_promotion.png"},"PriceList":{"title":"Price list","content":"Upgrade to present items, descriptions, and pricing within a cohesive structure that aligned perfectly with your site.","image":"https:\\/\\/assets.elementor.com\\/packages\\/v1\\/images\\/Price_list_promotion.png"},"PriceTable":{"title":"Price table","content":"Upgrade to build pricing matrices featuring highlighted columns, interactive check mark lists, and integrated action buttons.","image":"https:\\/\\/assets.elementor.com\\/packages\\/v1\\/images\\/Price_table_promotion.png"},"LoopGrid":{"title":"Loop Grid","content":"Upgrade to connect custom layouts directly to your site database, seamlessly rendering dynamic content queries that engage your site visitors.","image":"https:\\/\\/assets.elementor.com\\/packages\\/v1\\/images\\/Loop_grid_promotion.png"},"CallToAction":{"title":"Call to Action","content":"Upgrade to build Call to Action blocks with image overlays, custom hover animations, and promotional layout control across your site.","image":"https:\\/\\/assets.elementor.com\\/packages\\/v1\\/images\\/CTA_promotion.png"},"Template":{"title":"Template","content":"Upgrade to embed saved templates that sync automatically across your entire site, preserving layout integrity and accelerating your production speed.","image":"https:\\/\\/assets.elementor.com\\/packages\\/v1\\/images\\/Template_promotion.png"},"Gallery":{"title":"Gallery pro","content":"Upgrade to build gallery with dynamic categorization and custom layout control across your site.","image":"https:\\/\\/assets.elementor.com\\/packages\\/v1\\/images\\/Gallery_pro_promotion.png"},"MediaCarousel":{"title":"Media carousel","content":"Upgrade to build advanced Media Carousel with dynamic video elements into your sliders to better engage your site visitors.","image":"https:\\/\\/assets.elementor.com\\/packages\\/v1\\/images\\/Media_carousel_promotion.png"},"LoopCarousel":{"title":"Loop carousel","content":"Upgrade to build advanced Loop Carousel with dynamic posts, custom layouts seamlessly to better engage your site visitors.","image":"https:\\/\\/assets.elementor.com\\/packages\\/v1\\/images\\/Loop_carousel_promotion.png"}}]";}', 'off'),
