	(1556, 172, '_elementor_data', '[{"id":"5545328e","elType":"container","settings":{"flex_direction":"column","background_background":"classic","background_color":"#FFF8E3","padding":{"unit":"px","top":"60","right":"0","bottom":"20","left":"0","isLinked":false},"flex_gap":{"column":"0","row":"60","isLinked":false,"unit":"px","size":0},"css_classes":"according","boxed_width":{"unit":"px","size":1050,"sizes":[]},"padding_mobile":{"unit":"px","top":"40","right":"12","bottom":"40","left":"12","isLinked":false},"padding_tablet":{"unit":"px","top":"60","right":"12","bottom":"20","left":"12","isLinked":false},"background_image":{"url":"","id":"","size":""},"background_video_fallback":{"url":"","id":"","size":""},"background_slideshow_gallery":[],"background_hover_image":{"url":"","id":"","size":""},"background_hover_video_fallback":{"url":"","id":"","size":""},"background_hover_slideshow_gallery":[],"background_overlay_image":{"url":"","id":"","size":""},"background_overlay_video_fallback":{"url":"","id":"","size":""},"background_overlay_slideshow_gallery":[],"background_overlay_hover_image":{"url":"","id":"","size":""},"background_overlay_hover_video_fallback":{"url":"","id":"","size":""},"background_overlay_hover_slideshow_gallery":[]},"elements":[{"id":"59071215","elType":"widget","settings":{"title":"FREQUENTLY ASKED QUESTIONS","typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":40,"sizes":[]},"typography_font_weight":"900","title_color":"#096768","align":"center","_margin":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"header_size":"h3","typography_text_transform":"uppercase","typography_font_size_mobile":{"unit":"px","size":28,"sizes":[]},"typography_font_size_tablet":{"unit":"px","size":38,"sizes":[]},"_background_image":{"url":"","id":"","size":""},"_background_video_fallback":{"url":"","id":"","size":""},"_background_slideshow_gallery":[],"_background_hover_image":{"url":"","id":"","size":""},"_background_hover_video_fallback":{"url":"","id":"","size":""},"_background_hover_slideshow_gallery":[],"_mask_image":{"url":"","id":"","size":""}},"elements":[],"widgetType":"heading"},{"id":"705ac7aa","elType":"widget","settings":{"style":"style2","repeat":[{"block_title":"How can my clinic or hospital become a distributor of Baby Brands Gift Bags?","_id":"22d90ef","block_text":"Simply fill out our<a href=\\"https:\\/\\/babybrands.ca\\/app\\/front\\/distributor-registration\\" target=\\"_blank\\" style=\\"text-decoration: underline; color: inherit;\\"> distributor form<\\/a>   to get started."},{"block_title":"What types of healthcare providers are eligible to distribute Baby Brands Gift Club Bags?","block_text":"We partner with a variety of trusted healthcare professionals and services that care for new and expecting families, including Hospitals, Clinics, OB\\/GYN and Doctor offices, Doulas and Midwives, Prenatal\\/postnatal centers, Baby shows and community programs\\n","_id":"90d4327"},{"block_title":"Are there any costs involved with becoming a distributor?","block_text":"There is no cost to participate in the program. However, we will review the shipping costs to your location. If needed, we\\u2019ll contact you to discuss and confirm an agreement before accepting your distributor application.\\n","_id":"8a21f1e"},{"block_title":"How many gift bags will my center receive?\\n","block_text":"The number of bags you receive will depend on the volume of new and expecting parents your location sees on a monthly basis. We aim to supply you with the right amount based on your needs.","_id":"2c93300"},{"block_title":"Can I request additional bags if I run out?\\n","block_text":"Yes! If you need more gift bags due to higher-than-expected demand, just email us at info@babybrands.ca and we\\u2019ll do our best to fulfill your request quickly.\\n","_id":"640e9d5"},{"block_title":"Can I pause or cancel deliveries if needed?\\n","block_text":"Absolutely. If your clinic needs to pause, cancel, or adjust your deliveries, please reach out to info@babybrands.ca with your request.\\n","_id":"9f76ca0"},{"block_title":"How should I distribute the bags to patients?","block_text":"We recommend giving the bags directly to expecting or new parents during prenatal or postnatal appointments. This ensures they receive trusted product samples at a meaningful moment in their journey.\\n","_id":"d2b4a7f"},{"block_title":"Do I need to track or report how many bags are distributed?","block_text":"No formal reporting is required. However, if you notice a change in volume or feedback from parents, feel free to share it with us, we value your input and are always looking to improve the experience.","_id":"4b07973"},{"block_title":"Will I receive any promotional materials to display?\\n","block_text":"Yes! Upon request, we can provide free posters, easels, and information cards to help communicate the BabyBrands Gift Bag program in your waiting area.\\n","_id":"8072707"},{"block_title":"Who do I contact if I have more questions?\\n","block_text":"You can always reach our team at info@babybrands.ca, we\\u2019re happy to support you every step of the way.\\n","_id":"24cec0d"}],"_margin_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"_padding_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"image":{"id":169,"url":"http:\\/\\/localhost\\/samplits\\/wp-content\\/uploads\\/2026\\/08\\/placeholder.png"},"image2":{"id":170,"url":"http:\\/\\/localhost\\/samplits\\/wp-content\\/uploads\\/2026\\/08\\/placeholder-1.png"},"image3":{"id":171,"url":"http:\\/\\/localhost\\/samplits\\/wp-content\\/uploads\\/2026\\/08\\/placeholder-2.png"},"_background_image":{"url":"","id":"","size":""},"_background_video_fallback":{"url":"","id":"","size":""},"_background_slideshow_gallery":[],"_background_hover_image":{"url":"","id":"","size":""},"_background_hover_video_fallback":{"url":"","id":"","size":""},"_background_hover_slideshow_gallery":[],"_mask_image":{"url":"","id":"","size":""}},"elements":[],"widgetType":"kidsa-faq-with-image-widget"}],"isInner":false}]'),
