Linked":false},"flex_gap":{"column":"0","row":"60","isLinked":false,"unit":"px","size":0},"css_classes":"according","boxed_width":{"unit":"px","size":1050,"sizes":[]},"padding_mobile":{"unit":"px","top":"40","right":"12","bottom":"40","left":"12","isLinked":false},"padding_tablet":{"unit":"px","top":"60","right":"12","bottom":"20","left":"12","isLinked":false},"background_overlay_background":"classic","background_overlay_image":{"url":"http:\\/\\/localhost\\/samplits\\/wp-content\\/uploads\\/2026\\/08\\/faq-waves.webp","id":211,"size":"","alt":"","source":"library"},"background_overlay_position":"bottom center","background_overlay_position_tablet":"bottom center","background_overlay_position_mobile":"bottom center","background_overlay_ypos":{"unit":"px","size":560,"sizes":[]},"background_overlay_ypos_mobile":{"unit":"px","size":860,"sizes":[]},"background_overlay_repeat":"no-repeat","background_overlay_size":"contain","background_overlay_opacity":{"unit":"px","size":1,"sizes":[]},"margin":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true}},"elements":[{"id":"0b2d090","elType":"widget","settings":{"title":"Frequently Asked Questions","typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":40,"sizes":[]},"typography_font_weight":"900","title_color":"#096768","align":"center","_margin":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"typography_font_size_mobile":{"unit":"px","size":28,"sizes":[]},"typography_font_size_tablet":{"unit":"px","size":38,"sizes":[]}},"elements":[],"widgetType":"heading"},{"id":"59bab7b","elType":"widget","settings":{"style":"style2","repeat":[{"block_title":"How can my clinic or hospital become a distributor of Baby Brands Gift Bags?","_id":"22d90ef","block_text":"Simply fill out our<a href=\\"https:\\/\\/babybrands.ca\\/app\\/front\\/distributor-registration\\" target=\\"_blank\\" style=\\"text-decoration: underline; color: inherit;\\"> distributor form<\\/a>   to get started."},{"block_title":"What types of healthcare providers are eligible to distribute Baby Brands Gift Club Bags?","block_text":"We partner with a variety of trusted healthcare professionals and services that care for new and expecting families, including Hospitals, Clinics, OB\\/GYN and Doctor offices, Doulas and Midwives, Prenatal\\/postnatal centers, Baby shows and community programs\\n","_id":"90d4327"},{"block_title":"Are there any costs involved with becoming a distributor?","block_text":"There is no cost to participate in the program. However, we will review the shipping costs to your location. If needed, we\\u2019ll contact you to discuss and confirm an agreement before accepting your distributor application.\\n","_id":"8a21f1e"},{"block_title":"How many gift bags will my center receive?\\n","block_text":"The number of bags you receive will depend on the volume of new and expecting parents your location sees on a monthly basis. We aim to supply you with the right amount based on your needs.","_id":"2c93300"},{"block_title":"Can I request additional bags if I run out?\\n","block_text":"Yes! If you need more gift bags due to higher-than-expected demand, just email us at info@babybrands.ca and we\\u2019ll do our best to fulfill your request quickly.\\n","_id":"640e9d5"}],"_margin_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"_padding_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"image":{"id":169,"url":"http:\\/\\/localhost\\/samplits\\/wp-content\\/uploads\\/2026\\/08\\/placeholder.png"},"image2":{"id":170,"url":"http:\\/\\/localhost\\/samplits\\/wp-content\\/uploads\\/2026\\/08\\/placeholder-1.png"},"image3":{"id":171,"url":"http:\\/\\/localhost\\/samplits\\/wp-content\\/uploads\\/2026\\/08\\/placeholder-2.png"},"_margin":{"unit":"px","top":"0","right":"0","bottom":"160","left":"0","isLinked":false}},"elements":[],"widgetType":"kidsa-faq-with-image-widget"}],"isInner":false}]'),
